shell/left-sidebar-home/left-sidebar-hom:
/* Left Sidebar Home — quiet navigation index for the existing sidebar areas. */
#leftSidebarHome.left-sidebar-home {
  width: var(--left-sidebar-width, 320px);
  flex: 0 0 var(--left-sidebar-width, 320px);
  min-width: 0;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
  z-index: 41;
  background: var(--gtp-panel-bg);
  border: 1px solid var(--gtp-border);
  font-family: inherit;
  transition: width .25s ease, flex-basis .25s ease;
}

body.left-home-closed #leftSidebarHome.left-sidebar-home {
  width: 0;
  flex-basis: 0;
  border-width: 0;
  overflow: hidden;
  pointer-events: none;
}

.left-sidebar-home__header {
  position: relative;
  height: var(--gtp-header-height);
  flex: 0 0 var(--gtp-header-height);
  padding: 0 var(--gtp-header-padding-x);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  background: var(--gtp-bg);
  border: 0;
  border-bottom: 1px solid var(--gtp-border);
  margin: 0;
  width: 100%;
}

.left-sidebar-home__icon-button {
  border: 0;
  font: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.left-sidebar-home__title {
  min-width: 0;
  color: var(--gtp-text);
  font-size: var(--gtp-type-brand);
  font-weight: var(--gtp-weight-brand);
  letter-spacing: -0.025em;
}

.left-sidebar-home__brand-menu {
  min-width: 0;
  height: var(--gtp-header-control-size);
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--gtp-text);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font: inherit;
  cursor: pointer;
}
.left-sidebar-home__brand-menu:hover { background: transparent; }
.left-sidebar-home__brand-menu svg {
  width: 14px;
  height: 14px;
  color: var(--gtp-muted);
  stroke-width: 1.75;
}
.left-sidebar-home__brand-menu[aria-expanded="true"] { background: transparent; }
.left-sidebar-home__brand-menu[aria-expanded="true"] svg { transform: rotate(180deg); }

.left-sidebar-home__dropdown {
  position: absolute;
  top: calc(var(--gtp-header-height) - 6px);
  left: 10px;
  right: 10px;
  z-index: 50;
  padding: 6px;
  box-sizing: border-box;
  background: var(--gtp-surface-2);
  border: 1px solid var(--gtp-border-strong);
  border-radius: 12px;
  box-shadow: var(--gtp-shadow);
  font-family: var(--gtp-font-family);
}
.left-sidebar-home__dropdown.hidden { display: none; }
.left-sidebar-home__dropdown button {
  width: 100%;
  min-height: 42px;
  padding: 0 12px;
  border: 0;
  display: flex;
  align-items: center;
  border-radius: 8px;
  background: transparent;
  color: var(--gtp-text-2);
  font: inherit;
  font-size: var(--gtp-type-title);
  font-weight: var(--gtp-weight-title);
  letter-spacing: -0.015em;
  text-align: left;
  cursor: pointer;
}
.left-sidebar-home__dropdown button:hover { background: var(--gtp-surface-3); color: var(--gtp-text); }
.left-sidebar-home__dropdown svg { width: 17px; height: 17px; color: var(--gtp-muted); stroke-width: 1.9; }

.left-sidebar-home__actions { display: inline-flex; align-items: center; gap: 2px; }
.left-sidebar-home__icon-button {
  width: var(--gtp-header-control-size);
  height: var(--gtp-header-control-size);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: transparent;
  color: var(--gtp-muted);
}
.left-sidebar-home__icon-button:hover { background: var(--gtp-hover); color: var(--gtp-text); }
.left-sidebar-home__icon-button svg { width: var(--gtp-header-icon-size); height: var(--gtp-header-icon-size); stroke-width: 1.75; }

.left-sidebar-home__body {
  min-height: 0;
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 10px 10px 28px;
}

.left-sidebar-home__section-content {
  min-height: 0;
  flex: 1 1 auto;
  overflow: hidden;
}
.left-sidebar-home__section-content.hidden { display: none; }
.left-sidebar-home__section-content > #leftMarketSidebar,
.left-sidebar-home__section-content > #leftContextSidebar,
.left-sidebar-home__section-content > #leftEarningsCalendarSidebar,
.left-sidebar-home__section-content > #leftPluginSidebar {
  width: 100% !important;
  flex: 1 1 auto !important;
  height: 100%;
  border-right: 0 !important;
  pointer-events: auto !important;
}
.left-sidebar-home__section-content .market-sidebar-header,
.left-sidebar-home__section-content .context-sidebar-header,
.left-sidebar-home__section-content .earnings-calendar-sidebar__header,
.left-sidebar-home__section-content .plugin-sidebar-header {
  display: none;
}

.left-sidebar-home__menu {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.left-sidebar-home__menu-item {
  width: 100%;
  min-height: 42px;
  padding: 0 10px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--gtp-text-2);
  display: flex;
  align-items: center;
  gap: 11px;
  font: inherit;
  font-size: var(--gtp-type-item);
  font-weight: var(--gtp-weight-title);
  letter-spacing: -0.015em;
  text-align: left;
  cursor: pointer;
  transition: background-color .14s ease, color .14s ease;
  -webkit-tap-highlight-color: transparent;
}

.left-sidebar-home__menu-item:hover {
  background: var(--gtp-surface-2);
  color: var(--gtp-text);
}

.left-sidebar-home__menu-item.is-active {
  background: var(--gtp-surface-3);
  color: var(--gtp-text);
}

.left-sidebar-home__menu-item svg {
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
  color: var(--gtp-muted);
  stroke-width: 1.75;
}

.left-sidebar-home__menu-item.is-active svg {
  color: var(--gtp-text-2);
}

.left-sidebar-home__sections {
  margin-top: 24px;
  padding: 0 2px;
}

.left-sidebar-home__section {
  margin: 0 0 22px;
}

.left-sidebar-home__section:last-child {
  margin-bottom: 0;
}

.left-sidebar-home__section-head {
  min-height: 42px;
  padding: 0 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.left-sidebar-home__section-title {
  margin: 0;
  color: var(--gtp-text-2);
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: var(--gtp-type-item);
  font-weight: var(--gtp-weight-title);
  letter-spacing: -0.015em;
}
.left-sidebar-home__section-title svg { width: 17px; height: 17px; stroke-width: 1.75; color: var(--gtp-muted); }

.left-sidebar-home__section-menu {
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--gtp-faint);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background-color .14s ease, color .14s ease;
}

.left-sidebar-home__section-menu:hover {
  background: var(--gtp-surface-2);
  color: var(--gtp-text-2);
}

.left-sidebar-home__section-menu svg {
  width: 15px;
  height: 15px;
  stroke-width: 1.8;
  transition: transform .16s ease;
}
.left-sidebar-home__section-menu[aria-expanded="false"] svg { transform: rotate(-90deg); }

.left-sidebar-home__section-body[hidden] { display: none; }

.left-sidebar-home__items {
  margin: 2px 0 0;
  padding: 0;
  list-style: none;
}

.left-sidebar-home__item {
  min-width: 0;
  min-height: 36px;
  padding: 0 10px;
  display: flex;
  align-items: center;
  border-radius: 8px;
  color: var(--gtp-text-2);
  font-size: var(--gtp-type-item);
  font-weight: var(--gtp-weight-body);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.left-sidebar-home__item:hover {
  background: var(--gtp-surface-2);
  color: var(--gtp-text);
}

.left-sidebar-home__recent-link {
  display: block;
  width: 100%;
  min-width: 0;
  min-height: 36px;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: inherit;
  font-weight: inherit;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}

.left-sidebar-home__recent-link:focus-visible {
  outline: 1px solid var(--gtp-border-strong);
  outline-offset: -2px;
  border-radius: 6px;
}

.left-sidebar-home__empty {
  min-height: 34px;
  padding: 6px 10px;
  color: var(--gtp-faint);
  font-size: var(--gtp-type-fine);
  font-weight: var(--gtp-weight-meta);
  line-height: 1.45;
}

@media (max-width: 1023px) {
  #leftSidebarHome.left-sidebar-home {
    width: 100vw;
    flex-basis: 100vw;
    max-width: 100vw;
  }
  body.right-panel-open #leftSidebarHome.left-sidebar-home {
    width: 100vw;
    flex-basis: 100vw;
    max-width: 100vw;
  }
  body.left-home-closed #leftSidebarHome.left-sidebar-home { width: 0; flex-basis: 0; }
  body.left-home-open #rightPanel,
  body.left-home-open #rightPanelResizer { display: none !important; }
}

/* Sidebar Home — visual navigation/layout only.
   The primary menu deliberately does not open market/watchlist/plugin views yet. */
(function () {
  'use strict';

  const RECENT_STORAGE_KEY = 'gaemiGTP_recent_searches_v1';
  const RECENT_LIMIT = 10;
  let recentFallback = [];

  function readRecent() {
    try {
      const saved = localStorage.getItem(RECENT_STORAGE_KEY);
      if (!saved) return [];
      const entries = JSON.parse(saved);
      if (!Array.isArray(entries)) return [];
      return entries.filter((entry) => entry && ['stock', 'question'].includes(entry.type)
        && typeof entry.value === 'string' && entry.value.trim()
        && typeof entry.id === 'string' && entry.id.startsWith('conversation:')).slice(0, RECENT_LIMIT * 4);
    } catch (_) {
      return recentFallback.slice();
    }
  }

  function visibleRecent() {
    const mode = window.GaemiGTPAppState?.getCurrentAppMode?.() || 'gaemi';
    // Old entries had no mode metadata; keep them discoverable in all modes.
    return readRecent().filter(entry => !['gaemi', 'info', 'pro'].includes(entry.mode) || entry.mode === mode);
  }

  function renderRecent() {
    const list = document.getElementById('leftSidebarHomeRecentList');
    const empty = document.getElementById('leftSidebarHomeRecentEmpty');
    if (!list) return;
    const entries = visibleRecent();
    list.replaceChildren();
    entries.forEach((entry, index) => {
      const row = document.createElement('li');
      row.className = 'left-sidebar-home__item';
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'left-sidebar-home__recent-link';
      button.dataset.recentIndex = String(index);
      button.textContent = entry.value;
      button.title = entry.value;
      button.setAttribute('aria-label', `${entry.type === 'stock' ? '종목' : '질문'} 다시 열기: ${entry.value}`);
      row.appendChild(button);
      list.appendChild(row);
    });
    if (empty) empty.hidden = entries.length > 0;
  }

  function recordRecent(type, value, id, mode = null) {
    if (!['stock', 'question'].includes(type) || !String(id || '').startsWith('conversation:')) return null;
    const text = String(value || '').trim().slice(0, type === 'stock' ? 80 : 240);
    if (!text) return null;
    const entries = readRecent().filter((entry) => entry.id !== id);
    const selectedMode = ['gaemi', 'info', 'pro'].includes(mode) ? mode : window.GaemiGTPAppState?.getCurrentAppMode?.() || 'gaemi';
    const seenByMode = {};
    const next = [{ type, value: text, id, mode: selectedMode }, ...entries]
      .filter(entry => {
        const key = ['gaemi', 'info', 'pro'].includes(entry.mode) ? entry.mode : 'legacy';
        seenByMode[key] = (seenByMode[key] || 0) + 1;
        return seenByMode[key] <= RECENT_LIMIT;
      });
    recentFallback = next;
    try { localStorage.setItem(RECENT_STORAGE_KEY, JSON.stringify(next)); } catch (_) { /* browser storage unavailable */ }
    renderRecent();
    return id;
  }

  function getRecentIds() {
    return readRecent().map((entry) => entry.id);
  }

  function openRecent(index) {
    const entry = visibleRecent()[index];
    if (!entry) return;
    if (window.innerWidth < 1024) close();
    if (window.GaemiGTPApp?.restoreRecentConversation?.(entry.id)) {
      window.GaemiGTPCenterChatSearch?.enterChatWorkspace?.();
      applyState();
      return;
    }
    // A recent entry is a saved conversation, not a command to start new analysis.
    // Missing/corrupt history must not silently issue a new backend request.
    console.warn('[recent] Saved conversation is unavailable:', entry.id);
  }

  function escapeHtml(value) {
    return String(value)
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#039;');
  }

  function setActiveNav(id) {
    const target = id || 'home';
    document.querySelectorAll('#leftSidebarHome [data-left-home-nav]').forEach((button) => {
      const active = button.dataset.leftHomeNav === target;
      button.classList.toggle('is-active', active);
      if (active) button.setAttribute('aria-current', 'page');
      else button.removeAttribute('aria-current');
    });
  }

  function applyState() {
    window.GaemiGTPWorkspaceShellState?.apply?.();
  }

  function toggle() {
    if (typeof window.workspaceUIReady !== 'undefined' && !window.workspaceUIReady) return;
    const isOpen = document.body.classList.contains('left-home-open');
    if (isOpen) {
      document.body.classList.remove('left-home-open');
    } else {
      document.body.classList.remove('left-market-open', 'left-context-open', 'left-plugin-open');
      if (window.innerWidth < 1024) document.body.classList.remove('right-panel-open', 'right-panel-maximized');
      document.body.classList.add('left-home-open');
    }
    applyState();
  }

  function bindToggleControls() {
    document.querySelectorAll('[data-left-sidebar-toggle]').forEach((el) => {
      if (el.dataset.sidebarListenerBound === 'true') return;
      el.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        toggle();
      });
      el.dataset.sidebarListenerBound = 'true';
    });
  }

  function close() {
    document.body.classList.remove('left-home-open');
    applyState();
  }

  function toggleMenu() {
    const menu = document.getElementById('leftSidebarHomeMenu');
    const button = document.querySelector('[data-left-sidebar-home-menu-toggle]');
    if (!menu || !button) return;
    const open = menu.classList.toggle('hidden') === false;
    button.setAttribute('aria-expanded', String(open));
  }

  const sectionOrigins = new Map();

  function showSection(section = 'home') {
    if (typeof window.workspaceUIReady !== 'undefined' && !window.workspaceUIReady) return;
    const homeDefault = document.getElementById('leftSidebarHomeDefault');
    const host = document.getElementById('leftSidebarHomeSectionContent');
    const title = document.querySelector('.left-sidebar-home__title');
    if (!homeDefault || !host) return;

    sectionOrigins.forEach((origin, node) => {
      if (node.parentNode === host) {
        node.style.removeProperty('width');
        node.style.removeProperty('flex-basis');
        origin.parent.insertBefore(node, origin.nextSibling);
      }
    });
    sectionOrigins.clear();
    host.replaceChildren();
    host.classList.add('hidden');
    homeDefault.classList.remove('hidden');

    if (section !== 'home') {
      const idBySection = {
        market: 'leftMarketSidebar',
        context: 'leftContextSidebar',
        plugin: 'leftPluginSidebar'
      };
      const node = document.getElementById(idBySection[section]);
      if (!node || !node.parentNode) return;
      sectionOrigins.set(node, { parent: node.parentNode, nextSibling: node.nextSibling });
      host.appendChild(node);
      homeDefault.classList.add('hidden');
      host.classList.remove('hidden');
    }

    document.body.classList.add('left-home-open');
    document.body.classList.remove('left-market-open', 'left-context-open', 'left-plugin-open');
    document.getElementById('leftSidebarHomeMenu')?.classList.add('hidden');
    document.querySelector('[data-left-sidebar-home-menu-toggle]')?.setAttribute('aria-expanded', 'false');

    const embedded = host.firstElementChild;
    if (embedded) {
      embedded.removeAttribute('aria-hidden');
      embedded.style.width = '100%';
      embedded.style.flexBasis = '100%';
    }
    if (section === 'plugin') window.GaemiGTPPluginSidebar?.render?.();
    if (title) title.textContent = 'gaemiGTP';
    applyState();
  }

  function render() {
    const list = document.getElementById('leftSidebarHomePluginList');
    const empty = document.getElementById('leftSidebarHomePluginEmpty');
    if (!list) return;

    const catalog = window.GaemiGTPWidgetCatalog || {};
    const active = window.GaemiGTPWidgetDock?.getActiveIds?.() || [];
    const visible = active.filter((id) => catalog[id]);

    list.innerHTML = visible
      .map((id) => `<li class="left-sidebar-home__item">${escapeHtml(catalog[id].title)}</li>`)
      .join('');

    if (empty) empty.hidden = visible.length > 0;
    renderRecent();
    if (window.lucide) window.lucide.createIcons();
  }

  document.addEventListener('click', (event) => {
    const recentButton = event.target.closest('#leftSidebarHome [data-recent-index]');
    if (recentButton) {
      openRecent(Number(recentButton.dataset.recentIndex));
      return;
    }

    const navButton = event.target.closest('#leftSidebarHome [data-left-home-nav]');
    if (navButton) {
      const nav = navButton.dataset.leftHomeNav;
      setActiveNav(nav);
      return;
    }

    const sectionToggle = event.target.closest('#leftSidebarHome [data-left-home-section-toggle]');
    if (sectionToggle) {
      const bodyId = sectionToggle.getAttribute('aria-controls');
      const sectionBody = bodyId ? document.getElementById(bodyId) : null;
      if (!sectionBody) return;
      const expanded = sectionToggle.getAttribute('aria-expanded') !== 'false';
      sectionToggle.setAttribute('aria-expanded', String(!expanded));
      const sectionName = {
        watchlist: '관심종목', plugins: '플러그인', recent: '최근'
      }[sectionToggle.dataset.leftHomeSectionToggle] || '메뉴';
      sectionToggle.setAttribute('aria-label', `${sectionName} ${expanded ? '펼치기' : '접기'}`);
      sectionToggle.setAttribute('title', sectionToggle.getAttribute('aria-label'));
      sectionBody.hidden = expanded;
      return;
    }
  });

  window.GaemiGTPSidebarHome = { render, renderRecent, recordRecent, getRecentIds, setActiveNav, toggle, bindToggleControls, close, toggleMenu, showSection };
  window.addEventListener('storage', (event) => {
    if (event.key === RECENT_STORAGE_KEY) renderRecent();
  });
  window.toggleLeftSidebarHome = toggle;
  window.closeLeftSidebarHome = close;
  window.toggleLeftSidebarHomeMenu = toggleMenu;
  window.showLeftSidebarHomeSection = showSection;
  window.openLeftSidebarSection = showSection;

  document.addEventListener('DOMContentLoaded', () => {
    bindToggleControls();
    setActiveNav('home');
    render();
  });
}());

shell/right-panel/right-panel-grid.css:
/* Right Panel Dashboard Grid — layout skeleton only.
   Scope: #rightPanelGrid only.
   News/disclosures remain outside this grid.
   No widget/data/chat/API behavior belongs in this file. */

#rightPanelGrid {
  --right-panel-grid-columns: 12;
  --right-panel-grid-gap: 10px;

  /* Standard vertical sizes from the dashboard grid plan. */
  --right-panel-height-s: 240px;
  --right-panel-height-m: 320px;
  --right-panel-height-l: 400px;
  --right-panel-height-xl: 480px;
  --right-panel-height-xxl: 560px;

  width: 100%;
  min-height: 100%;
  box-sizing: border-box;
  display: grid;
  grid-template-columns: repeat(var(--right-panel-grid-columns), minmax(0, 1fr));
  grid-auto-flow: row;
  grid-auto-rows: minmax(0, auto);
  gap: var(--right-panel-grid-gap);
  align-content: start;
}

/* Width rules for future dashboard widgets. */
#rightPanelGrid > [data-grid-span="3"] { grid-column: span 3; }
#rightPanelGrid > [data-grid-span="4"] { grid-column: span 4; }
#rightPanelGrid > [data-grid-span="6"] { grid-column: span 6; }
#rightPanelGrid > [data-grid-span="8"] { grid-column: span 8; }
#rightPanelGrid > [data-grid-span="12"] { grid-column: 1 / -1; }

/* Standard height rules. Nothing uses these until a dashboard widget opts in. */
#rightPanelGrid > [data-grid-height="s"] { height: var(--right-panel-height-s); }
#rightPanelGrid > [data-grid-height="m"] { height: var(--right-panel-height-m); }
#rightPanelGrid > [data-grid-height="l"] { height: var(--right-panel-height-l); }
#rightPanelGrid > [data-grid-height="xl"] { height: var(--right-panel-height-xl); }
#rightPanelGrid > [data-grid-height="xxl"] { height: var(--right-panel-height-xxl); }

#rightPanelGrid > [data-grid-span],
#rightPanelGrid > [data-grid-height] {
  min-width: 0;
  box-sizing: border-box;
}

shell/right-panel/right-panel-tabs.css:
/* Right Panel Tabs — v7.5
   상단 탭만 담당한다. 위젯/데이터 스타일은 각 페이지/위젯에서 담당한다.
*/

.right-panel-header {
  min-width: 0;
  height: var(--gtp-header-height) !important;
  min-height: var(--gtp-header-height) !important;
  padding-inline: var(--gtp-header-padding-x) !important;
  overflow: visible;
  position: relative;
  z-index: 100;
  border-bottom: 1px solid var(--gtp-border) !important;
  background: var(--gtp-bg) !important;
}
.right-panel-tabs { display: flex; align-items: center; gap: 3px; min-width: 0; height: 100%; overflow-x: visible; scrollbar-width: none; padding: 0 2px; }
.right-panel-tabs::-webkit-scrollbar { display: none; }

.right-panel-header .icon-hit {
  width: var(--gtp-header-control-size) !important;
  height: var(--gtp-header-control-size) !important;
  min-width: var(--gtp-header-control-size) !important;
  min-height: var(--gtp-header-control-size) !important;
}

.right-panel-header .icon-hit svg {
  width: var(--gtp-header-icon-size) !important;
  height: var(--gtp-header-icon-size) !important;
}
.right-panel-tab { height: 32px; max-width: 150px; flex: 0 0 auto; display: inline-flex; align-items: center; gap: 0; padding: 0 9px; border: 0; border-radius: 9px; background: transparent; color: var(--gtp-faint); cursor: pointer; transition: background .15s ease, color .15s ease, border-color .15s ease; font: inherit; }
.right-panel-tab:hover { color: var(--gtp-text-2); background: var(--gtp-hover); }
