.right-panel-tab-add:hover { color: var(--gtp-text); background: var(--gtp-active); }
.right-panel-tab-menu { position: absolute; top: calc(100% + 6px); right: 0; z-index: 50; width: 176px; padding: 6px; border: 1px solid var(--gtp-border-strong); border-radius: 12px; background: var(--gtp-surface-2); box-shadow: var(--gtp-shadow); font-family: var(--gtp-font-family); }
