.right-panel-tab-add svg { width: var(--gtp-header-icon-size); height: var(--gtp-header-icon-size); }
.right-panel-tab-view { width: 100%; height: 100%; min-height: 0; }
.right-panel-tab-view[hidden] { display: none !important; }
.right-panel-tab-placeholder { min-height: 100%; box-sizing: border-box; padding: 40px 24px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.right-panel-tab-placeholder__icon { width: 44px; height: 44px; margin-bottom: 12px; display: inline-flex; align-items: center; justify-content: center; border: 1px solid var(--gtp-border); border-radius: 14px; background: var(--gtp-surface-2); color: var(--gtp-faint); }
.right-panel-tab-placeholder__icon svg { width: 20px; height: 20px; }
