.right-panel-related-news {
  height: 100%;
  min-height: 0;
  overflow-y: auto;
  padding: 12px 10px 22px;
  box-sizing: border-box;
}
.right-panel-related-news__heading {
  margin: 0 0 14px;
  color: var(--gtp-text);
  font-size: var(--gtp-type-title);
  font-weight: var(--gtp-weight-title);
  line-height: 1.4;
}
.right-panel-related-news__list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.right-panel-related-news__item {
  padding: 11px 10px;
}
.right-panel-related-news__title {
  color: var(--gtp-text-2);
  font-size: var(--gtp-type-title);
  font-weight: var(--gtp-weight-title);
  line-height: 1.45;
}
.right-panel-related-news__description {
  margin-top: 5px;
  color: var(--gtp-muted);
  font-size: var(--gtp-type-meta);
  font-weight: var(--gtp-weight-body);
  line-height: 1.55;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
.right-panel-related-news__meta {
  margin-top: 6px;
  color: var(--gtp-faint);
  font-size: var(--gtp-type-fine);
  font-weight: var(--gtp-weight-meta);
  line-height: 1.4;
}
.right-panel-related-news__empty {
  color: var(--gtp-faint);
  font-size: var(--gtp-type-meta);
}
@media (max-width: 480px) {
  .right-panel-related-news { padding: 10px 8px 20px; }
  .right-panel-related-news__item { padding: 10px 9px; }
}

.right-panel-related-news__item {
  width: 100%;
  margin: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
  font: inherit;
}
.right-panel-related-news__item {
  border-radius: 9px;
  transition: background-color 160ms ease;
}
.right-panel-related-news__item:hover,
.right-panel-related-news__item:focus-visible {
  background: var(--gtp-surface-2);
}

.right-panel-related-news__item:focus-visible {
  outline: 1px solid var(--gtp-border-strong);
  outline-offset: -1px;
}


/* 공시 패널 전용: 클릭 기능 없이 공시 한 건의 영역만 hover로 구분한다. */
.right-panel-disclosures__item {
  cursor: default;
}
.right-panel-disclosures__line {
  width: 100%;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-top: 7px;
  color: var(--gtp-faint);
  font-size: var(--gtp-type-meta);
  font-weight: var(--gtp-weight-meta);
  line-height: 1.4;
  font-family: inherit;
}
.right-panel-disclosures__line:first-child {
  margin-top: 0;
}
.right-panel-disclosures__title {
  color: var(--gtp-faint);
  font-size: var(--gtp-type-meta);
  font-weight: var(--gtp-weight-title);
}
.right-panel-disclosures__line > span:last-child:not(:first-child) {
  margin-left: auto;
  text-align: right;
}

