shell/right-panel/right-panel.css:
@import url('./right-panel-grid.css');

/* Right Panel Shell — fixed three-column panel. */
#gaemiWorkspace { --right-panel-width: calc((100vw - 58px) / 4); }

#gaemiWorkspace #rightPanel {
  order: 3;
  flex: 0 0 var(--right-panel-width);
  width: var(--right-panel-width);
  min-width: 240px;
  max-width: none;
  height: 100%;
  border-left: 0 !important;
  background: var(--gtp-bg);
}

/* 고정 폭 패널의 세로 구분선. 드래그 손잡이가 아니다. */
#gaemiWorkspace #rightPanelResizer {
  order: 2;
  position: relative;
  flex: 0 0 10px;
  width: 10px;
  height: 100%;
  cursor: default;
  background: transparent;
  z-index: 20;
  pointer-events: none;
}
#gaemiWorkspace #rightPanelResizer::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
  background: var(--gtp-border);
}
html.dark #gaemiWorkspace #rightPanelResizer::after { background: var(--gtp-border); }

body.right-panel-closed #rightPanel,
body.right-panel-closed #rightPanelResizer,
body:not(.right-panel-open) #rightPanel,
body:not(.right-panel-open) #rightPanelResizer { display: none !important; }

@media (min-width: 1024px) {
  #gaemiWorkspace #rightPanel { min-width: 240px; }
  body.right-panel-open:not(.right-panel-maximized) #gaemiWorkspace #rightPanel { border-left: 0; }
  body.right-panel-open:not(.right-panel-maximized) #gaemiWorkspace #mainContent {
    flex: 1 1 auto !important;
    width: auto !important;
    min-width: 300px !important;
    max-width: none !important;
  }
  body.right-panel-maximized #gaemiWorkspace #mainContent { display: none !important; }
  body.right-panel-maximized #gaemiWorkspace #rightPanelResizer { display: none !important; }
  body.right-panel-maximized #gaemiWorkspace #rightPanel {
    flex: 1 1 auto !important;
    width: auto !important;
    max-width: none !important;
    min-width: 0 !important;
  }
}

@media (max-width: 1023px) {
  #gaemiWorkspace #rightPanel {
    flex-basis: min(var(--right-panel-width), 100vw);
    width: min(var(--right-panel-width), 100vw);
    min-width: 240px;
  }
  body.right-panel-open #gaemiWorkspace #mainContent { display: none !important; }
  body.right-panel-open #gaemiWorkspace #rightPanelResizer { display: none !important; }
  body.right-panel-open #gaemiWorkspace #rightPanel {
    flex: 0 0 100dvw !important;
    width: 100dvw !important;
    max-width: 100dvw !important;
    min-width: 0 !important;
  }
  #rightPanel [data-panel-maximize] { display: none !important; }
}

shell/right-panel/right-panel.js:
/* Right Panel Shell Controller — fixed three-column desktop panel. */
(function () {
  'use strict';

  const DEFAULT_PANEL_WIDTH_RATIO = 3 / 12;
  const MIN_PANEL_WIDTH = 240;
  const MIN_CHAT_WIDTH = 300;

  function getWorkspace() { return document.getElementById('gaemiWorkspace'); }
  function getWorkAreaWidth() {
    return Math.max(0, window.innerWidth);
  }
  function clampWidth(width) {
    const max = Math.max(MIN_PANEL_WIDTH, getWorkAreaWidth() - MIN_CHAT_WIDTH);
    return Math.max(MIN_PANEL_WIDTH, Math.min(Math.round(width), max));
  }
  function getDefaultPanelWidth() { return clampWidth(getWorkAreaWidth() * DEFAULT_PANEL_WIDTH_RATIO); }
  function applyPanelWidth() {
    const workspace = getWorkspace(); if (!workspace) return;
    const rounded = getDefaultPanelWidth();
    workspace.style.setProperty('--right-panel-width', `${rounded}px`);
    return rounded;
  }
  function setPanelWidth() { return applyPanelWidth(); }
  function applyState() { window.GaemiGTPWorkspaceShellState?.apply?.(); }

  function toggle() {
    const isOpen = document.body.classList.contains('right-panel-open');
    if (isOpen) {
      document.body.classList.remove('right-panel-open', 'right-panel-maximized');
    } else {
      if (window.innerWidth < 1024) {
        document.body.classList.remove('left-home-open', 'left-market-open', 'left-context-open', 'left-plugin-open');
      }
      document.body.classList.add('right-panel-open');
    }
    applyState();
  }

  function toggleMaximize() {
    if (!document.body.classList.contains('right-panel-open')) {
      if (window.innerWidth < 1024) {
        document.body.classList.remove('left-home-open', 'left-market-open', 'left-context-open', 'left-plugin-open');
      }
      document.body.classList.add('right-panel-open');
    }
    const maximized = document.body.classList.toggle('right-panel-maximized');
    const button = document.querySelector('[data-panel-maximize]');
    if (button) {
      button.setAttribute('aria-label', maximized ? '패널 원래 크기로' : '패널 최대화');
      button.setAttribute('title', maximized ? '패널 원래 크기로' : '패널 최대화');
    }
    if (!maximized) requestAnimationFrame(() => setPanelWidth());
    applyState();
  }

  function initializeWorkspaceInteractions() {
    const workspace = getWorkspace();
    const panel = document.getElementById('rightPanel');
    if (!workspace || !panel || panel.dataset.rightPanelBound === 'true') return;

    setPanelWidth();
    window.addEventListener('resize', () => {
      if (!document.body.classList.contains('right-panel-maximized')) setPanelWidth();
    });
    panel.dataset.rightPanelBound = 'true';
  }

  window.GaemiGTPRightPanelShell = { getWorkspace, getWorkAreaWidth, setPanelWidth, toggle, toggleMaximize, initializeWorkspaceInteractions };
  window.toggleRightPanel = toggle;
  window.toggleRightPanelMaximize = toggleMaximize;
})();
